/**
 * Import flow controller (UI-020 / issue #25; docs/GUI_UX_SPEC.md §3/§4/§20).
 *
 * Framework-free: App subscribes to state + screen events; tests drive it
 * with fake ports. The controller owns the §27 import-side transitions —
 *
 *   EMPTY ─pick/drop→ OPENING_AUDIO ─ok→ AUDIO_READY
 *                         ├─ unsupported/corrupt → AUDIO_ERROR ─閉じる→ EMPTY
 *                         └─ (audio already loaded: error surfaces as a
 *                             dialog issue over the kept workspace)
 *   recent project ─→ OPENING_AUDIO ─source ok→ AUDIO_READY
 *                         └─ path/hash failure → SOURCE_MISSING
 *                                └─ 音源を指定 → hash ok → AUDIO_READY
 *                                                mismatch → SOURCE_MISSING
 *
 * Error policy (§20): state what failed, what is kept, the next action —
 * a failed re-import never destroys a loaded audio session, and the source
 * file is only ever read (FND-001: identity = content hash, not location).
 */
import type { ScreenState } from "../workspace/screen";
import { ja } from "../strings/ja";
import { type ImportPorts } from "./ports";
import { audioFormatOf, baseName, projectDisplayName } from "./formats";
import {
  markAutoOpenFailed,
  recordRecentProject,
  loadRecentProjects,
} from "./recentProjects";
import type {
  AudioFileRef,
  AudioFormat,
  ImportIssue,
  LoadedAudio,
  MediaSource,
  ProjectSummary,
  RecentProjectEntry,
  RecordedAudioRef,
  SourceMissingInfo,
} from "./types";

export type ImportPhase =
  "idle" | "opening" | "ready" | "error" | "sourceMissing";

export interface ImportState {
  readonly phase: ImportPhase;
  /** File/project name shown while `phase === "opening"`. */
  readonly openingLabel: string | null;
  /** "audio" | "project" selects the loading copy variant. */
  readonly openingKind: "audio" | "project" | null;
  readonly audio: LoadedAudio | null;
  /** Recoverable failure — card content on AUDIO_ERROR, dialog content
      when the workspace already has audio (the error never destroys it). */
  readonly issue: ImportIssue | null;
  readonly sourceMissing: SourceMissingInfo | null;
}

export const INITIAL_IMPORT_STATE: ImportState = {
  phase: "idle",
  openingLabel: null,
  openingKind: null,
  audio: null,
  issue: null,
  sourceMissing: null,
};

export interface ImportEvents {
  /** Screen transitions owned by the import flow (§27). */
  onScreenChange(screen: ScreenState): void;
  /** Mirrors state for React consumers. */
  onState(state: ImportState): void;
  /** aria-live status bar announcements (role="status"). */
  announce(message: string): void;
  /** Recent-projects list changed (persisted + UI). */
  onRecentChange(entries: readonly RecentProjectEntry[]): void;
  /** Decoded audio is ready — host wires it into the transport adapter. */
  onAudioReady(audio: LoadedAudio): void;
  /** Optional (#106): the opened project carried a saved score — the
   *  host restores it and jumps to SCORE_READY instead of waiting for
   *  a re-transcription. Fires after the usual state/screen updates. */
  onProjectScoreReady?(
    result: unknown,
    project: {
      projectId: string;
      /** #221: the .hornscribe.json this score came from — the host's
       *  Ctrl+S saves back to it without re-picking a path. */
      path: string;
      sourceHash: string | null;
      // #265: the recorded source path — the host keeps it so a
      // SOURCE_MISSING save preserves the relink target.
      sourcePath: string | null;
      /** #391: the project document came from the `.recovery` sibling
       *  — the host keeps the restored doc dirty so the next save
       *  repairs the unreadable main file. */
      recovered?: boolean;
    },
  ): void;
  /** Optional (#264): a project document was opened (or relinked) —
   *  fires before onAudioReady so the host can restore the saved
   *  transcription settings into 採譜オプション before the audio
   *  slot resets them to global defaults. */
  onProjectOpened?(project: ProjectSummary): void;
}

type RecentStorage = Pick<Storage, "getItem" | "setItem"> | null;

export class ImportController {
  private state: ImportState = INITIAL_IMPORT_STATE;
  /** Serialization guard: a superseded open (user re-picked mid-load) must
      not overwrite newer state when it resolves late. */
  private generation = 0;

  constructor(
    private readonly ports: ImportPorts,
    private readonly events: ImportEvents,
    private readonly storage: RecentStorage = null,
  ) {}

  getState(): ImportState {
    return this.state;
  }

  /** `file.openAudio` (Ctrl+O / 開く / drop fallback): pick then import. */
  async openViaDialog(): Promise<void> {
    let ref: AudioFileRef | null;
    try {
      ref = await this.ports.pickAudio();
    } catch {
      // A picker failure is not a file error — surface the generic
      // open-failure issue rather than an unhandled rejection.
      this.fail({ kind: "openFailed" });
      return;
    }
    if (!ref) return; // cancel is silent — not an error
    await this.importRefs([ref]);
  }

  /**
   * Drag&drop / dialog entry point. With several files the first supported
   * one wins (single-document app); zero supported → honest format error.
   */
  async importRefs(refs: readonly AudioFileRef[]): Promise<void> {
    if (refs.length === 0) return;
    // #348: single-document app — when several files arrive, say so
    // instead of silently taking the first supported one.
    if (refs.length > 1) {
      this.events.announce(ja.import.feedback.multiFileNotice);
    }
    // A dropped/picked .hornscribe.json is a project open, not an audio
    // import — the dialog's "all files" escape hatch can hand one over.
    const projRef = refs.find((r) => r.name.endsWith(".hornscribe.json"));
    if (projRef) {
      const bytes = projRef.kind === "file" ? projRef.file : undefined;
      await this.openProject(
        {
          name: projectDisplayName(projRef.name),
          path: projRef.kind === "path" ? projRef.path : "",
          openedAt: Date.now(),
        },
        bytes,
      );
      return;
    }
    const ref = refs.find((r) => audioFormatOf(r.name) !== null) ?? refs[0];
    const format = audioFormatOf(ref.name);
    if (format === null) {
      this.fail({ kind: "unsupported", fileName: ref.name });
      return;
    }
    await this.importAudioRef(ref, format);
  }

  /**
   * FEAT-001 (#60): 録音バッファを直接取り込む(PC音源/マイク録音)。
   * `ref` は `kind:"recording"` で、`blob` は WAV または MediaRecorder
   * 出力(ブラウザ dev)。拡張子は常に `.wav`/`.webm` を仮定するため
   * `audioFormatOf` の allowlist を迂回して良い(録音由来なので形式は
   * 自明)。失敗時は openFailed に落とす。
   */
  async importRecording(ref: RecordedAudioRef): Promise<void> {
    const gen = this.begin("audio", ref.name);
    try {
      // #230: a persisted recording probes natively — no byte copy,
      // playback streams via media://.
      const probe =
        ref.path && this.ports.probeAudio
          ? await this.ports.probeAudio(ref.path)
          : null;
      if (!this.isCurrent(gen)) return;
      if (probe) {
        const audio: LoadedAudio = {
          ref: { ...ref, contentHash: probe.contentHash },
          fileName: ref.name,
          format: "wav",
          sizeBytes: probe.sizeBytes,
          durationSeconds: probe.durationSeconds,
          sampleRate: probe.sampleRate,
          peaks: probe.peaks,
          mediaSource: { kind: "url", url: probe.playbackUrl },
        };
        this.setState({
          phase: "ready",
          openingLabel: null,
          openingKind: null,
          audio,
          issue: null,
          sourceMissing: null,
        });
        this.events.onAudioReady(audio);
        this.events.announce(
          ref.source === "loopback"
            ? "PCの音を取り込みました(" + ref.name + ")"
            : "録音を取り込みました(" + ref.name + ")",
        );
        return;
      }
      // Tauri 録音は保存済みファイルを読む(#70: 実ファイル=リリンク可能)。
      const blob = ref.blob ?? (await this.ports.readAudioBytes(ref.path!));
      const contentHash = ref.path
        ? await this.ports.sha256Hex(blob)
        : undefined;
      const decoded = await this.ports.decodeAudio(blob, ref.name);
      if (!this.isCurrent(gen)) return;
      const audio: LoadedAudio = {
        ref: { ...ref, contentHash },
        fileName: ref.name,
        // 録音物は decode 可能なコンテナなので拡張子は実質 wav。
        format: "wav",
        sizeBytes: blob.size,
        durationSeconds: decoded.durationSeconds,
        sampleRate: decoded.sampleRate,
        peaks: decoded.peaks,
        mediaSource: { kind: "blob", blob },
      };
      this.setState({
        phase: "ready",
        openingLabel: null,
        openingKind: null,
        audio,
        issue: null,
        sourceMissing: null,
      });
      this.events.onAudioReady(audio);
      this.events.announce(
        ref.source === "loopback"
          ? `PCの音を取り込みました(${ref.name})`
          : `録音を取り込みました(${ref.name})`,
      );
    } catch {
      if (!this.isCurrent(gen)) return;
      this.fail({ kind: "openFailed", fileName: ref.name });
    }
  }

  /** OPENING_AUDIO → AUDIO_READY, or AUDIO_ERROR. */
  private async importAudioRef(
    ref: AudioFileRef,
    format: AudioFormat,
  ): Promise<void> {
    const gen = this.begin("audio", ref.name);
    try {
      // #230: path-backed sources probe natively — hash/metadata/peaks
      // in Rust, playback streamed via media:// — so the file's bytes
      // never enter the webview. kind:"file" refs and probe failures
      // keep the byte path.
      const probe =
        ref.kind === "path" && this.ports.probeAudio
          ? await this.ports.probeAudio(ref.path)
          : null;
      if (!this.isCurrent(gen)) return;
      if (probe) {
        const audio: LoadedAudio = {
          ref: { ...ref, contentHash: probe.contentHash },
          fileName: ref.name,
          format,
          sizeBytes: probe.sizeBytes,
          durationSeconds: probe.durationSeconds,
          sampleRate: probe.sampleRate,
          peaks: probe.peaks,
          mediaSource: { kind: "url", url: probe.playbackUrl },
        };
        this.setState({
          phase: "ready",
          openingLabel: null,
          openingKind: null,
          audio,
          issue: null,
          sourceMissing: null,
        });
        this.events.onAudioReady(audio);
        this.events.announce(ja.import.feedback.loaded(ref.name));
        return;
      }
      const blob = await this.blobFor(ref);
      // #243: the content hash is the source identity (FND-001) —
      // computing it once at import lets project save write a real
      // contentHash instead of the empty string that broke reopen.
      const contentHash = await this.ports.sha256Hex(blob);
      const decoded = await this.ports.decodeAudio(blob, ref.name);
      if (!this.isCurrent(gen)) return;
      const audio: LoadedAudio = {
        ref: { ...ref, contentHash },
        fileName: ref.name,
        format,
        sizeBytes: blob.size,
        durationSeconds: decoded.durationSeconds,
        sampleRate: decoded.sampleRate,
        peaks: decoded.peaks,
        mediaSource: { kind: "blob", blob },
      };
      this.setState({
        phase: "ready",
        openingLabel: null,
        openingKind: null,
        audio,
        issue: null,
        sourceMissing: null,
      });
      this.events.onAudioReady(audio);
      this.events.announce(ja.import.feedback.loaded(ref.name));
    } catch {
      if (!this.isCurrent(gen)) return;
      this.fail({ kind: "openFailed", fileName: ref.name });
    }
  }

  /**
   * 最近使ったプロジェクト → verify the recorded source path (store.py
   * `verify_source_audio`: exists + content hash) → AUDIO_READY, else
   * SOURCE_MISSING with the relink action.
   * `bytes` carries a browser-dev File ref (no durable path — the
   * project is opened but not recorded in the recents list).
   */
  async openProject(entry: RecentProjectEntry, bytes?: Blob): Promise<void> {
    const gen = this.begin("project", entry.name);
    try {
      // #365: when the engine-backed inspector is wired, the document is
      // migrated + validated by `project.open` (same funnel as
      // project.save); the lighter local parser remains only as the
      // no-engine browser-dev fallback.
      const { document: data, recovered } = bytes
        ? await this.projectDocumentFromBytes(bytes)
        : await this.projectDocumentFromPath(entry.path);
      // Browser-dev File refs have no durable path — project.path
      // stays "" so touchRecent skips them; the display name comes
      // from the file name instead.
      const project = projectSummaryFromDocument(
        data,
        entry.path,
        entry.path ? undefined : entry.name,
        recovered,
      );
      // #147: record the project's sourceAudio ref into the persistent
      // index — survives MRU truncation, covers SOURCE_MISSING opens too
      // (the project file still references the source until re-saved).
      // #221: byte-opened projects (autosave restore, browser File
      // drops) have no durable path — indexing an empty key would
      // pollute the source-ref store.
      if (project.path) {
        this.ports.updateSourceRef?.(project.path, project.sourcePath);
      }
      if (!this.isCurrent(gen)) return;
      if (!project.sourcePath || !project.sourceHash) {
        this.enterSourceMissing(project, false);
        return;
      }
      // #230: probe the recorded source natively — hash verify +
      // metadata/peaks + media:// playback, with zero bytes in the
      // webview. Probe failure falls back to the byte path below.
      if (this.ports.probeAudio) {
        const probe = await this.ports.probeAudio(project.sourcePath);
        if (!this.isCurrent(gen)) return;
        if (probe) {
          if (probe.contentHash !== project.sourceHash) {
            // File at the recorded path exists but content differs —
            // store.py treats this like a moved source (verify fails).
            this.enterSourceMissing(project, false);
            return;
          }
          this.finishProjectOpen(
            project,
            {
              kind: "path",
              path: project.sourcePath,
              name: baseName(project.sourcePath),
            },
            {
              sizeBytes: probe.sizeBytes,
              durationSeconds: probe.durationSeconds,
              sampleRate: probe.sampleRate,
              peaks: probe.peaks,
              mediaSource: { kind: "url", url: probe.playbackUrl },
            },
          );
          return;
        }
      }
      let audioBlob: Blob;
      try {
        audioBlob = await this.ports.readAudioBytes(project.sourcePath);
      } catch {
        if (!this.isCurrent(gen)) return;
        this.enterSourceMissing(project, false);
        return;
      }
      const hash = await this.ports.sha256Hex(audioBlob);
      if (!this.isCurrent(gen)) return;
      if (hash !== project.sourceHash) {
        // File at the recorded path exists but content differs —
        // store.py treats this like a moved source (verify fails).
        this.enterSourceMissing(project, false);
        return;
      }
      try {
        const decoded = await this.ports.decodeAudio(audioBlob, entry.name);
        if (!this.isCurrent(gen)) return;
        this.finishProjectOpen(
          project,
          {
            kind: "path",
            path: project.sourcePath,
            name: baseName(project.sourcePath),
          },
          {
            sizeBytes: audioBlob.size,
            durationSeconds: decoded.durationSeconds,
            sampleRate: decoded.sampleRate,
            peaks: decoded.peaks,
            mediaSource: { kind: "blob", blob: audioBlob },
          },
        );
      } catch {
        if (!this.isCurrent(gen)) return;
        this.fail({
          kind: "openFailed",
          fileName: baseName(project.sourcePath),
        });
      }
    } catch {
      if (!this.isCurrent(gen)) return;
      // #364: a failed open marks the path so the launch auto-open
      // cannot error-loop on the same dead MRU head every start; the
      // path rides the issue so the error card can offer 履歴から削除.
      if (entry.path) markAutoOpenFailed(entry.path);
      this.fail({
        kind: "projectOpenFailed",
        fileName: entry.name,
        path: entry.path || undefined,
      });
    }
  }

  /** SOURCE_MISSING: 「音源を指定」 — pick a candidate then verify. */
  async pickRelinkSource(): Promise<void> {
    let ref: AudioFileRef | null;
    try {
      ref = await this.ports.pickAudio();
    } catch {
      // Picker failure while relinking — stay on the SOURCE_MISSING card
      // and say what happened; the user can retry 音源を指定.
      this.events.announce(ja.import.errors.openFailedBody);
      return;
    }
    if (!ref) return;
    await this.relinkWith(ref);
  }

  /**
   * Hash-based relink, the same contract as
   * `ProjectStore.relink_source_audio`: the candidate must hash to the
   * recorded content hash — identity is content, not location.
   */
  async relinkWith(ref: AudioFileRef): Promise<void> {
    const sm = this.state.sourceMissing;
    if (!sm) return;
    const gen = this.begin("project", sm.project.name);
    try {
      // #230: a path-backed candidate verifies + probes natively — the
      // bytes never enter the webview; kind:"file" and probe failures
      // keep the byte path.
      if (ref.kind === "path" && this.ports.probeAudio) {
        const probe = await this.ports.probeAudio(ref.path);
        if (!this.isCurrent(gen)) return;
        if (probe) {
          if (probe.contentHash !== sm.project.sourceHash) {
            this.enterSourceMissing(sm.project, true);
            return;
          }
          const format = audioFormatOf(ref.name) ?? "wav";
          const audio: LoadedAudio = {
            // #234: the verified project hash is the audio identity.
            ref: { ...ref, contentHash: sm.project.sourceHash ?? probe.contentHash },
            fileName: ref.name,
            format,
            sizeBytes: probe.sizeBytes,
            durationSeconds: probe.durationSeconds,
            sampleRate: probe.sampleRate,
            peaks: probe.peaks,
            mediaSource: { kind: "url", url: probe.playbackUrl },
          };
          this.finishRelink(sm.project, audio);
          return;
        }
      }
      const blob = await this.blobFor(ref);
      const hash = await this.ports.sha256Hex(blob);
      if (!this.isCurrent(gen)) return;
      if (hash !== sm.project.sourceHash) {
        this.enterSourceMissing(sm.project, true);
        return;
      }
      const decoded = await this.ports.decodeAudio(blob, ref.name);
      if (!this.isCurrent(gen)) return;
      const format = audioFormatOf(ref.name) ?? "wav";
      const audio: LoadedAudio = {
        // #234: carry the verified hash so the audio identity matches
        // the project's recorded sourceHash — a relinked source
        // keeps its restored score instead of invalidating it.
        ref: { ...ref, contentHash: sm.project.sourceHash ?? hash },
        fileName: ref.name,
        format,
        sizeBytes: blob.size,
        durationSeconds: decoded.durationSeconds,
        sampleRate: decoded.sampleRate,
        peaks: decoded.peaks,
        mediaSource: { kind: "blob", blob },
      };
      this.finishRelink(sm.project, audio);
    } catch {
      if (!this.isCurrent(gen)) return;
      // Candidate unreadable or undecodable after a hash match — stay on
      // the missing-source card; the status line carries what happened
      // (the card itself already offers the retry action).
      this.enterSourceMissing(sm.project, false);
      this.events.announce(ja.import.errors.openFailedBody);
    }
  }

  /** Relink success tail — shared by the native-probe and byte paths. */
  private finishRelink(project: ProjectSummary, audio: LoadedAudio): void {
    this.setState({
      phase: "ready",
      openingLabel: null,
      openingKind: null,
      audio,
      issue: null,
      sourceMissing: null,
    });
    this.touchRecent(project);
    // #264: relink resumes the same project — restore its saved
    // 採譜 settings before the audio slot resets options.
    this.events.onProjectOpened?.(project);
    this.events.onAudioReady(audio);
    // #106: the project's saved score (already restored in the
    // background) can now land — the relinked audio matches the
    // recorded content hash.
    if (project.scoreResult != null) {
      this.events.onProjectScoreReady?.(project.scoreResult, {
        projectId: project.projectId,
        path: project.path,
        sourceHash: project.sourceHash,
        sourcePath: project.sourcePath,
        recovered: project.recovered,
      });
      this.announceOpened(project);
    } else {
      // #391: the restore notice outranks the routine relink one.
      this.announceOpened(project, ja.import.feedback.sourceRelinked);
    }
  }

  /** 閉じる on AUDIO_ERROR / SOURCE_MISSING → EMPTY; on a kept workspace
      (issue dialog over audio) it only clears the issue. */
  dismiss(): void {
    if (this.state.phase === "error" || this.state.phase === "sourceMissing") {
      this.setState({ ...INITIAL_IMPORT_STATE });
      return;
    }
    if (this.state.issue) {
      this.setState({ ...this.state, issue: null });
    }
  }

  /** Recent entries (host renders them in the EMPTY state). */
  recentProjects(): RecentProjectEntry[] {
    return loadRecentProjects(this.storage);
  }

  /* ----------------------------- internals ----------------------------- */

  private begin(kind: "audio" | "project", label: string): number {
    const gen = ++this.generation;
    this.setState({
      phase: "opening",
      openingLabel: label,
      openingKind: kind,
      audio: this.state.audio,
      issue: null,
      sourceMissing: null,
    });
    return gen;
  }

  private isCurrent(gen: number): boolean {
    return gen === this.generation;
  }

  /** `project.open` by path — the worker reads the file itself, so no
   *  bytes cross the webview. Falls back to the local parser where no
   *  engine exists (browser dev). */
  private async projectDocumentFromPath(
    path: string,
  ): Promise<{ document: Record<string, unknown>; recovered: boolean }> {
    const inspect = this.ports.inspectProject;
    if (inspect) {
      const res = await inspect({ path });
      // #391: `recovered` marks a .recovery-sibling restore — the
      // browser-dev parser has no such sibling so it stays false.
      return { document: res.project, recovered: res.recovered === true };
    }
    const blob = await this.ports.readProjectBytes(path);
    return {
      document: parseProjectJson(await blob.arrayBuffer()),
      recovered: false,
    };
  }

  /** `project.open` by bytes — File drops and autosave snapshots ride
   *  `documentBase64` so they take the identical migrate+validate path
   *  as a disk open (#365 acceptance). */
  private async projectDocumentFromBytes(
    bytes: Blob,
  ): Promise<{ document: Record<string, unknown>; recovered: boolean }> {
    const inspect = this.ports.inspectProject;
    if (inspect) {
      const res = await inspect({
        documentBase64: await blobToBase64(bytes),
      });
      // Byte-opens have no durable path — there is no .recovery
      // sibling to restore from, so a success is never `recovered`.
      return { document: res.project, recovered: false };
    }
    return { document: parseProjectJson(await bytes.arrayBuffer()), recovered: false };
  }

  private fail(issue: ImportIssue): void {
    if (this.state.audio) {
      // Workspace is alive — the issue becomes a dialog over it, the
      // loaded audio/waveform/transport all stay (§20 "what is kept").
      this.setState({ ...this.state, phase: "ready", issue });
    } else {
      this.setState({
        phase: "error",
        openingLabel: null,
        openingKind: null,
        audio: null,
        issue,
        sourceMissing: null,
      });
    }
  }

  private enterSourceMissing(project: ProjectSummary, mismatch: boolean): void {
    this.setState({
      phase: "sourceMissing",
      openingLabel: null,
      openingKind: null,
      audio: null,
      issue: null,
      sourceMissing: { project, mismatch },
    });
    // #106: the score survives a missing/moved source — restore it
    // now; the audio can be relinked afterwards.
    if (project.scoreResult != null) {
      this.events.onProjectScoreReady?.(project.scoreResult, {
        projectId: project.projectId,
        path: project.path,
        sourceHash: project.sourceHash,
        sourcePath: project.sourcePath,
        recovered: project.recovered,
      });
    }
    // #391: a .recovery restore has no card of its own — the status
    // line carries the notice alongside the SOURCE_MISSING card.
    if (project.recovered) {
      this.events.announce(ja.import.feedback.projectRecovered(project.name));
    }
  }

  private finishProjectOpen(
    project: ProjectSummary,
    ref: AudioFileRef,
    media: {
      sizeBytes: number;
      durationSeconds: number;
      sampleRate: number;
      peaks: readonly number[];
      mediaSource: MediaSource;
    },
  ): void {
    const format = audioFormatOf(ref.name) ?? "wav";
    const audio: LoadedAudio = {
      // #234: the recorded project hash is this audio's verified
      // content identity — carry it so identity checks line up.
      ref: { ...ref, contentHash: project.sourceHash ?? undefined },
      fileName: ref.name,
      format,
      sizeBytes: media.sizeBytes,
      durationSeconds: media.durationSeconds,
      sampleRate: media.sampleRate,
      peaks: media.peaks,
      mediaSource: media.mediaSource,
    };
    this.setState({
      phase: "ready",
      openingLabel: null,
      openingKind: null,
      audio,
      issue: null,
      sourceMissing: null,
    });
    this.touchRecent(project);
    // #264: restore the saved 採譜 settings before the host's audio
    // slot logic runs — 採譜し直す must default to the conditions
    // that produced this project, not current global defaults.
    this.events.onProjectOpened?.(project);
    this.events.onAudioReady(audio);
    // #106: a project saved with score extras skips re-transcription —
    // the host restores the document and lands on SCORE_READY.
    if (project.scoreResult != null) {
      this.events.onProjectScoreReady?.(project.scoreResult, {
        projectId: project.projectId,
        path: project.path,
        sourceHash: project.sourceHash,
        sourcePath: project.sourcePath,
        recovered: project.recovered,
      });
      this.announceOpened(project);
    } else {
      // #391: even a score-less restore must surface the recovery —
      // the user needs to know the main file is broken.
      this.announceOpened(project, ja.import.feedback.loaded(ref.name));
    }
  }

  /** Project-open announce — a `.recovery` restore overrides the usual
   *  opened/loaded notice: "your file was broken, we restored the
   *  backup" outranks the routine message (#391). */
  private announceOpened(project: ProjectSummary, fallback?: string): void {
    this.events.announce(
      project.recovered
        ? ja.import.feedback.projectRecovered(project.name)
        : (fallback ?? ja.import.feedback.projectOpened(project.name)),
    );
  }

  private touchRecent(project: ProjectSummary): void {
    // A project opened from browser bytes has no durable path — the
    // recents list only records entries that can actually be reopened.
    if (!project.path) return;
    const list = recordRecentProject(
      { name: project.name, path: project.path },
      this.storage,
    );
    this.events.onRecentChange(list);
  }

  private async blobFor(ref: AudioFileRef): Promise<Blob> {
    return ref.kind === "file" ? ref.file : this.ports.readAudioBytes(ref.path);
  }

  private setState(next: ImportState): void {
    this.state = next;
    this.events.onState(next);
    const screen = screenForPhase(next.phase);
    if (screen) this.events.onScreenChange(screen);
  }
}

/** The screen states the import flow drives; "ready" is the last one it
    owns — later transitions belong to the transcription/score features. */
function screenForPhase(phase: ImportPhase): ScreenState | null {
  switch (phase) {
    case "idle":
      return "empty";
    case "opening":
      return "openingAudio";
    case "ready":
      return "audioReady";
    case "error":
      return "audioError";
    case "sourceMissing":
      return "sourceMissing";
  }
}

/* --------------------------- project parsing --------------------------- */

/**
 * UTF-8 bytes → raw project dict (JSON.parse only — no validation).
 * Engine-routed opens skip this: `project.open` parses worker-side.
 */
function parseProjectJson(bytes: ArrayBuffer): Record<string, unknown> {
  const data = JSON.parse(new TextDecoder().decode(bytes)) as Record<
    string,
    unknown
  >;
  if (typeof data !== "object" || data === null) {
    throw new Error("project document is not an object");
  }
  return data;
}

/** UTF-8-safe base64 for `documentBase64` payloads — chunked so large
 *  project documents stay under the String.fromCharCode arg limit. */
async function blobToBase64(bytes: Blob): Promise<string> {
  const buf = new Uint8Array(await bytes.arrayBuffer());
  let bin = "";
  const CHUNK = 0x8000;
  for (let i = 0; i < buf.length; i += CHUNK) {
    bin += String.fromCharCode(...buf.subarray(i, i + CHUNK));
  }
  return btoa(bin);
}

/**
 * Parse a `.hornscribe.json` document into the relink-relevant summary
 * (schema v1 — mirrors `HornScribeProject.from_dict`). Throws on malformed
 * or unsupported documents → caller maps to `projectOpenFailed`.
 *
 * This is the browser-dev/no-engine fallback parser; production opens go
 * through `project.open` on the worker (#365), which returns the already
 * normalized dict to {@link projectSummaryFromDocument}.
 */
export function parseProjectFile(
  bytes: ArrayBuffer,
  path: string,
  displayName?: string,
): ProjectSummary {
  return projectSummaryFromDocument(parseProjectJson(bytes), path, displayName);
}

/**
 * Dict → {@link ProjectSummary} — the extraction both open paths share.
 * The schema checks stay as a defensive floor: the local fallback needs
 * them, and they document the version the shell understands (#365).
 */
function projectSummaryFromDocument(
  data: Record<string, unknown>,
  path: string,
  displayName?: string,
  recovered?: boolean,
): ProjectSummary {
  if (data.schemaVersion !== 1) {
    throw new Error(`unsupported schemaVersion: ${String(data.schemaVersion)}`);
  }
  if (typeof data.projectId !== "string" || data.projectId === "") {
    throw new Error("projectId is missing or malformed");
  }
  const source = data.sourceAudio as Record<string, unknown> | null;
  return {
    path,
    projectId: data.projectId,
    name: displayName ?? projectDisplayName(path),
    sourcePath:
      source && typeof source.originalPath === "string"
        ? source.originalPath
        : null,
    sourceHash:
      source && typeof source.contentHash === "string"
        ? source.contentHash
        : null,
   scoreResult: scoreResultFromProject(data),
    transcriptionSettings: transcriptionSettingsFromProject(data),
    recovered: recovered || undefined,
  };
}

/**
 * Reassemble the completed-job `result` shape from the project's saved
 * extras (#106). `engineDocumentFromResult` and `scoreHandoffFromResult`
 * consume this directly — the score is restored without re-transcribing.
 * Returns null when the file carries no MusicXML (externally authored
 * projects keep the AUDIO_READY-only open path).
 */
function scoreResultFromProject(
  data: Record<string, unknown>,
): Record<string, unknown> | null {
  const concert = data.musicXmlConcert;
  const horn = data.musicXmlHornF;
  if (typeof concert !== "string" || typeof horn !== "string") {
    return null;
  }
  const score = data.score as Record<string, unknown> | null;
  return {
    musicXmlConcert: concert,
    musicXmlHornF: horn,
    scoreRevision:
      score && typeof score.revision === "string"
        ? score.revision
        : "rev-project",
    reviewIssues: Array.isArray(data.reviewIssues) ? data.reviewIssues : [],
    scoreDocument: data.scoreDocument ?? null,
    meta: data.meta ?? {},
  };
}

/** #264: `transcription.settings` echo from the project file — the
 *  authoritative provenance of the conditions that produced the
 *  score. Unknown/malformed values stay raw here; the options mapper
 *  (transcriptionParams) validates them into UI state. */
function transcriptionSettingsFromProject(
  data: Record<string, unknown>,
): Record<string, unknown> | null {
  const record = data.transcription as Record<string, unknown> | null;
  const settings = record?.settings;
  if (typeof settings !== "object" || settings === null) return null;
  return settings as Record<string, unknown>;
}

/**
 * Import ports — the typed seams between the import controller and its
 * environment (UI-020; mirrors the port/adapter style used by the UI-004
 * TransportController contract).
 *
 * `ImportController` depends only on this interface, so tests drive fake
 * ports and the production wiring (`runtimePorts.ts`) selects Tauri IPC or
 * browser fallbacks per capability — never by sniffing in the controller.
 */
import type { AudioFileRef } from "./types";

/** Result of decoding audio for display (waveform + metadata). */
export interface DecodedAudio {
  durationSeconds: number;
  sampleRate: number;
  /** Normalized peak amplitudes 0–1. */
  peaks: readonly number[];
}

/** Thrown by `decodeAudio` when the bytes cannot be decoded — the
 *  controller maps it to the recoverable `openFailed` issue. */
export class AudioDecodeError extends Error {
  constructor(message = "decodeAudioData failed") {
    super(message);
    this.name = "AudioDecodeError";
  }
}

export interface ImportPorts {
  /**
   * Show the file picker (Tauri dialog plugin; `<input type=file>` in
   * browser dev). Resolves null when the user cancels — cancel is not an
   * error and never surfaces copy.
   */
  pickAudio(): Promise<AudioFileRef | null>;
  /** Bytes of a `kind:"path"` ref (Rust `read_audio_bytes` command). */
  readAudioBytes(path: string): Promise<Blob>;
  /** Bytes of a `.hornscribe.json` project file (`read_project_file`). */
  readProjectBytes(path: string): Promise<Blob>;
  /** Optional (#365): engine-side `project.open` — migrate_project_dict +
   *  HornScribeProject.from_dict on the worker returns the normalized
   *  current-schema dict (extras preserved). Absent in plain-browser dev,
   *  where the controller falls back to its lighter local parser. */
  inspectProject?(
    ref: { path: string } | { documentBase64: string },
  ): Promise<{
    path: string;
    project: Record<string, unknown>;
    /** #391: the main file failed and the response came from the
     *  sibling `.recovery` snapshot — the host surfaces the restore
     *  and keeps the document dirty so the next save repairs the
     *  main file. */
    recovered?: boolean;
  }>;
  /** Decode audio for the waveform/metadata (WebAudio decodeAudioData). */
  decodeAudio(blob: Blob, fileName: string): Promise<DecodedAudio>;
  /**
   * SHA-256 of file contents as lowercase hex — the same contract as
   * `hash_file_sha256` in python/hornscribe/project/model.py, so relink
   * verification matches `ProjectStore.relink_source_audio`.
   */
  sha256Hex(blob: Blob): Promise<string>;

  /** Optional (#147): record the opened/saved project's sourceAudio ref
   *  into the persistent source-ref index (appDataDir/source-refs.json)
   *  so references survive MRU truncation. Fire-and-forget — failures
   *  must not fail the open. */
  updateSourceRef?(projectPath: string, sourcePath: string | null): void;

  /** Optional (#230): probe a path-backed source natively — streaming
   *  hash, WAV/ffmpeg metadata + peaks, and a media:// playback URL —
   *  so the file's bytes never enter the webview. Returns null when the
   *  native probe is unavailable or fails; callers fall back to the
   *  byte-copy path. */
  probeAudio?(path: string): Promise<AudioProbe | null>;
}

/** Native probe result (#230) — everything AUDIO_READY needs without
 *  a Blob of the source. */
export interface AudioProbe {
  durationSeconds: number;
  sampleRate: number;
  channels: number;
  sizeBytes: number;
  /** SHA-256 of the source — same identity contract as sha256Hex. */
  contentHash: string;
  peaks: readonly number[];
  /** media:// URL for <audio> playback (Range-capable). */
  playbackUrl: string;
}

/**
 * Import domain types (issue #25 / UI-020; docs/GUI_UX_SPEC.md §3/§4/§20).
 *
 * The import flow turns a user-picked file into a `LoadedAudio` the shell
 * can draw (waveform peaks + metadata) and play (UI-004 TransportController
 * contract media source), or into a recoverable `ImportIssue` rendered with
 * the copy-deck error shape (what failed / what is kept / next action).
 */

/** Advertised container formats (GUI_UX_SPEC §3: WAV・MP3・FLAC・M4A・OGG). */
export type AudioFormat = "wav" | "mp3" | "flac" | "m4a" | "ogg";

/**
 * A user-selected audio file. Inside Tauri the native dialog and the
 * window drag-drop event hand us real filesystem paths; in plain-browser
 * dev sessions the HTML drop/file-input hands us `File` objects.
 */
export type AudioFileRef =
  | { kind: "path"; path: string; name: string; contentHash?: string }
  | { kind: "file"; file: File; name: string; contentHash?: string };

/**
 * FEAT-001 (#60): 録音由来の疑似ファイル参照。
 * `kind: "recording"` はディスク上の実ファイルではなく、メモリ上の
 * 録音バッファを表す。`mediaSource.blob` に録音結果が入るので、
 * `LoadedAudio` としては既存経路と同じ振る舞いをする。
 */
export type RecordedAudioRef = {
  kind: "recording";
  /** UI 表示用の仮想ファイル名(例: "録音_20260922_153000.wav")。 */
  name: string;
  /** "loopback" | "microphone" — どこから録ったか。 */
  source: "loopback" | "microphone";
  /** Tauri: appDataDir/recordings/ に保存済みの実ファイルパス(#70)。
   *  ある場合は内容がディスク上に永続化されており、プロジェクトの
   *  sourceAudio(originalPath/contentHash)に載せられる。 */
  path?: string;
  /** path を持つ録音の SHA-256(FND-001 の contentHash 契約)。 */
  contentHash?: string;
  /** ブラウザ dev 等、実ファイルが無い場合の録音バイト列。 */
  blob?: Blob;
};

/**
 * What the UI-004 TransportController contract can load — mirrors the
 * spike's `AudioSource` (url | blob). We always hand over a blob: either
 * the dropped `File` itself or a Blob built from `read_audio_bytes`, so the
 * user-owned source file is only ever read, never modified.
 */
export type MediaSource = { kind: "url"; url: string } | { kind: "blob"; blob: Blob };

/** Fully decoded audio ready for the AUDIO_READY state (GUI_UX_SPEC §4). */
export interface LoadedAudio {
  /** Where the bytes came from (kept for relink/re-open bookkeeping). */
  ref: AudioFileRef | RecordedAudioRef;
  fileName: string;
  format: AudioFormat;
  sizeBytes: number;
  /** Audio-clock duration in seconds (0 while unknown). */
  durationSeconds: number;
  sampleRate: number;
  /** Normalized peak amplitudes 0–1 for the waveform strip. */
  peaks: readonly number[];
  /** Playback-ready source for the transport adapter. */
  mediaSource: MediaSource;
}

/**
 * Recoverable import failures — every variant has a copy-deck title/body
 * plus a recovery action, so errors never dead-end (acceptance: "invalid
 * file has actionable Japanese error", "unsupported codec does not
 * dead-end").
 */
export type ImportIssue =
  /** Extension is not in the advertised set — honest format guidance. */
  | { kind: "unsupported"; fileName: string }
  /** Read/decode failed (corrupt file, vanished path, codec the webview
      cannot decode and FFmpeg normalization has not landed yet). */
  | { kind: "openFailed"; fileName?: string }
  /** `.hornscribe.json` could not be read or parsed. `path` is the MRU
   *  path that failed — powers the 履歴から削除 action on the error card
   *  and the launch auto-open skip set (#364); absent for byte-opens. */
  | { kind: "projectOpenFailed"; fileName: string; path?: string };

/**
 * The subset of `HornScribeProject` (python/hornscribe/project/model.py,
 * schema v1) the relink UX needs. `sourcePath`/`sourceHash` mirror
 * `sourceAudio.originalPath` / `contentHash`.
 */
export interface ProjectSummary {
  /** Absolute path of the .hornscribe.json file itself. */
  path: string;
  projectId: string;
  /** Display name — file basename without the .hornscribe.json suffix. */
  name: string;
  sourcePath: string | null;
  sourceHash: string | null;
  /** Saved job-result extras (#106): when the file carries
   *  musicXmlConcert/musicXmlHornF + score.revision + reviewIssues,
   *  this mirrors the completed-job `result` payload so the score can
   *  be restored without re-transcribing. Null for projects without
   *  saved score data (externally authored files). */
 scoreResult: unknown | null;
  /** #264: the saved `transcription.settings` echo (provenance). The
   *  host restores it into 採譜オプション so 採譜し直す reruns under
   *  the conditions that produced this project, not the current
   *  global defaults. Null for externally authored files. */
  transcriptionSettings: Record<string, unknown> | null;
  /** #391: the open came from the `.recovery` sibling because the main
   *  file was unreadable — the host announces the restore and keeps the
   *  document dirty so Ctrl+S repairs the main file. */
  recovered?: boolean;
}

/** SOURCE_MISSING context: which project lost its audio, and whether the
 *  last relink candidate failed the content-hash check (deck:
 *  sourceMoved vs sourceHashMismatch copy). */
export interface SourceMissingInfo {
  project: ProjectSummary;
  mismatch: boolean;
}

/** A "最近使ったプロジェクト" entry (GUI_UX_SPEC §3). */
export interface RecentProjectEntry {
  name: string;
  path: string;
  /** Epoch ms of the last successful open (sorting + pruning). */
  openedAt: number;
}

/**
 * 採譜オプション (GUI_UX_SPEC §4 advanced options — hidden in the popover
 * next to 採譜を開始). Values are option keys; Japanese labels resolve via
 * ja.import.audioOptions. Consumed by the transcription feature (UI-040),
 * persisted nowhere yet.
 */
export interface TranscriptionOptions {
  tempo: "auto" | "manual";
  tempoBpm: number | null;
  meter: string;
  minDuration: string;
  triplets: "auto" | "allow" | "none";
  simplicity: "standard" | "simple" | "detailed";
  range: "all" | "selection";
  /** 音源の種類 — mono=単旋律楽器, melody=メロディ優先(ミックス/JPOP),
      auto=重なりの多さからエンジンが自動判定。 */
  texture: "auto" | "mono" | "melody" | "voices" | "chords";
  /** #189: per-job engine override. "auto" inherits the global
   *  設定→詳細設定 backend; an explicit choice pins this job only. */
  backend: "auto" | "basicPitch" | "pyin";
  /** #187: opt-in vocal isolation — the backend runs on a
   *  center-extracted vocal estimate instead of the raw mix. */
  vocalIsolation: boolean;
  /** 範囲指定時の開始/終了（秒）。null = 音声の端まで。 */
  selectionStartSec: number | null;
  selectionEndSec: number | null;
}

export const DEFAULT_TRANSCRIPTION_OPTIONS: TranscriptionOptions = {
  tempo: "auto",
  tempoBpm: null,
  meter: "auto",
  minDuration: "16",
  triplets: "auto",
  simplicity: "standard",
  range: "all",
  texture: "auto",
  backend: "auto",
  vocalIsolation: false,
  selectionStartSec: null,
  selectionEndSec: null,
};

/**
 * TranscriptionSession — the app-facing engine/job state machine
 * (GUI_UX_SPEC §5, §27; ADR-0002 failure model).
 *
 * One job at a time (the worker enforces `maxConcurrentJobs: 1`).
 * The session owns a {@link SidecarClient} built on a port factory, so a
 * crashed worker can be replaced by a fresh spawn without restarting the
 * UI — restart is an explicit recovery action, never silent resubmission.
 *
 * State is exposed as an immutable {@link SessionSnapshot} via
 * `subscribe()` — React consumes it through a single `useEffect`, and the
 * §27 screen machine maps it to `transcribing` / `transcriptionError` /
 * `scoreReady` / `audioReady`.
 */

import { SidecarClient, type SidecarClientOptions } from "./client";
import {
  ERR,
  SidecarError,
  type EngineCapabilities,
  type EngineInfo,
  type JobEventPayload,
  type JobStartResult,
} from "./protocol";
import type { SidecarPort } from "./port";
import {
  createJobView,
  markCancelling,
  markJobDead,
  reduceJobEvent,
  type JobView,
} from "./jobView";
import { extractReviewIssueCount } from "./review";

/** Real transcription job kind; the spike worker only knows
 *  `demoLongTask`, so the session falls back to it when `transcription`
 *  is not in `capabilities.jobKinds` — documented as the UI-002→UI-040
 *  bridge until the engine ships the real kind. */
export const TRANSCRIPTION_JOB_KIND = "transcription";
export const FALLBACK_JOB_KIND = "demoLongTask";

export type EngineStatus =
  /** No client yet (never started, or torn down). */
  | "offline"
  /** Spawn + handshake in flight. */
  | "starting"
  /** Handshake done — the engine can accept jobs. */
  | "ready"
  /** Worker exited unexpectedly (crash). Restart is an explicit action. */
  | "crashed"
  /** Watchdog: worker stopped answering mid-job. */
  | "unresponsive"
  /** Graceful shutdown completed. */
  | "closed";

/**
 * The failure classes the §20 error surfaces distinguish:
 * - `transcriptionFailed` — the job ended in a terminal `failed` event
 *   while the engine stayed alive → 再試行 is meaningful.
 * - `workerCrashed` — the process died mid-job → エンジンを再起動.
 * - `workerNotResponding` — watchdog probe timed out → エンジンを再起動.
 */
export type FailureKind =
  | "transcriptionFailed"
  | "workerCrashed"
  | "workerNotResponding";

export interface SessionFailure {
  kind: FailureKind;
  /** Machine-readable detail for the diagnostics surface — codes and
   *  engine messages stay OUT of normal UI copy (JAPANESE_UI_COPY §7). */
  detail: string;
  errorCode?: string;
  /** ENGINE_DEPENDENCY_MISSING only: the missing package name, carried
   *  so the error surface can name what to install (#195). */
  errorPackage?: string;
}

export interface SessionSnapshot {
  engine: EngineStatus;
  engineInfo: EngineInfo | null;
  capabilities: EngineCapabilities | null;
  /** In-flight or just-ended job — null when idle. */
  job: JobView | null;
  /** Set on terminal failure; cleared on retry/restart/dismiss. */
  failure: SessionFailure | null;
  /**
   * The `completed` event's `result` payload — the score-data handoff
   * point. UI-030's adapter consumes this to build the canonical score
   * view; UI-040 only guarantees it is preserved verbatim and never
   * mutated by the progress layer.
   */
  lastResult: unknown;
  /** Count of open review issues in `lastResult` (0 when none). */
  reviewIssueCount: number;
  /** Recent supervision diagnostics (stderr + client notes). Ring buffer. */
  diagnostics: readonly string[];
}

type Listener = (snapshot: SessionSnapshot) => void;

export interface TranscriptionSessionOptions {
  portFactory: () => SidecarPort;
  clientOptions?: SidecarClientOptions;
  /** Max retained diagnostic lines. */
  diagnosticLogLimit?: number;
  /** #233: grace between the cooperative job.cancel ack and the
   *  terminate+restart fallback. Blocking inference cannot answer
   *  mid-call, so a terminal event that never arrives within this
   *  window escalates to killing the worker and respawning a fresh
   *  engine. */
  cancelGraceMs?: number;
  /** Wall clock — injectable for tests. */
  now?: () => number;
}

const DEFAULT_DIAGNOSTIC_LIMIT = 80;
const DEFAULT_CANCEL_GRACE_MS = 4_000;

export class TranscriptionSession {
  private readonly portFactory: () => SidecarPort;
  private readonly clientOptions?: SidecarClientOptions;
  private readonly logLimit: number;
  private readonly cancelGraceMs: number;
  private readonly now: () => number;
  private client: SidecarClient | null = null;
  private readonly listeners = new Set<Listener>();
  private snap: SessionSnapshot = {
    engine: "offline",
    engineInfo: null,
    capabilities: null,
    job: null,
    failure: null,
    lastResult: null,
    reviewIssueCount: 0,
    diagnostics: [],
  };
  private logLines: string[] = [];

  constructor(opts: TranscriptionSessionOptions) {
    this.portFactory = opts.portFactory;
    this.clientOptions = opts.clientOptions;
    this.logLimit = opts.diagnosticLogLimit ?? DEFAULT_DIAGNOSTIC_LIMIT;
    this.cancelGraceMs = opts.cancelGraceMs ?? DEFAULT_CANCEL_GRACE_MS;
    this.now = opts.now ?? (() => Date.now());
  }

  // ---- subscription -------------------------------------------------------

  getSnapshot(): SessionSnapshot {
    return this.snap;
  }

  subscribe(cb: Listener): () => void {
    this.listeners.add(cb);
    return () => this.listeners.delete(cb);
  }

  private update(patch: Partial<SessionSnapshot>): void {
    this.snap = { ...this.snap, ...patch };
    for (const cb of [...this.listeners]) cb(this.snap);
  }

  private log(line: string): void {
    this.logLines = [...this.logLines.slice(-(this.logLimit - 1)), line];
    this.update({ diagnostics: this.logLines });
  }

  // ---- engine lifecycle ------------------------------------------------------

  private buildClient(): SidecarClient {
    const client = new SidecarClient(this.portFactory(), this.clientOptions);
    // #233: only the CURRENT client may move the session — a replaced
    // worker's late exit/state frames must not downgrade the fresh
    // engine or rewrite the settled job view.
    client.onJobEvent((e) => {
      if (this.client === client) this.onJobEvent(e);
    });
    client.onStateChange((s) => {
      if (this.client === client) this.onClientState(s);
    });
    client.onDiagnostic((l) => this.log(l));
    return client;
  }

  /** Lazily spawn + handshake. Idempotent while `ready`. */
  private async ensureEngine(): Promise<void> {
    if (this.client && this.snap.engine === "ready") return;
    this.update({ engine: "starting" });
    const client = this.buildClient();
    this.client = client;
    try {
      const hs = await client.start();
      this.update({
        engine: "ready",
        engineInfo: hs.engineInfo,
        capabilities: hs.capabilities,
      });
    } catch (e) {
      // Spawn/handshake failure → the engine is down, the error surface
      // offers エンジンを再起動 (which builds a fresh port+client).
      this.update({
        engine: "crashed",
        failure: {
          kind: "workerNotResponding",
          detail: e instanceof Error ? e.message : String(e),
          errorCode: e instanceof SidecarError ? e.code : undefined,
        },
      });
      throw e;
    }
  }

  /**
   * エンジンを再起動 — the crash/unresponsive recovery action (§20).
   * Tears down the old client (best-effort shutdown, then kill) and runs
   * a fresh spawn + handshake. Never resubmits a job.
   */
  async restartEngine(): Promise<void> {
    const old = this.client;
    this.client = null;
    if (old) {
      // #233: await the teardown — shutdown() now kills the worker when
      // the graceful path times out, and the respawn must not race a
      // still-living process (ENGINE_ALREADY_RUNNING).
      await old.shutdown(800).catch(() => undefined);
    }
    this.update({ engine: "starting", failure: null });
    const client = this.buildClient();
    this.client = client;
    try {
      const hs = await client.start();
      this.update({
        engine: "ready",
        engineInfo: hs.engineInfo,
        capabilities: hs.capabilities,
      });
    } catch (e) {
      this.update({
        engine: "crashed",
        failure: {
          kind: "workerNotResponding",
          detail: e instanceof Error ? e.message : String(e),
          errorCode: e instanceof SidecarError ? e.code : undefined,
        },
      });
      throw e;
    }
  }

  /** Graceful teardown for app shutdown — never throws. */
  async dispose(): Promise<void> {
    const client = this.client;
    this.client = null;
    if (client) await client.shutdown();
    this.update({ engine: "closed" });
  }

  /**
   * `project.save` (#100): persist a .hornscribe.json document through
   * the engine. Spawns the engine lazily when it is not already up —
   * the same engine that produced the score normally still serves.
   */
  async saveProject(path: string, project: unknown): Promise<{ path: string; projectId: string }> {
    await this.ensureEngine();
    const client = this.client;
    if (!client) {
      throw new SidecarError(ERR.ENGINE_UNAVAILABLE, "no engine client");
    }
    return client.call<{ path: string; projectId: string }>(
      "project.save",
      { path, project },
    );
  }

  /**
   * `project.open` (#365): the authoritative open path — the worker
   * reads (or decodes), migrates and validates the document, and returns
   * the normalized current-schema dict. `path` covers MRU/disk opens;
   * `documentBase64` covers byte-opens (File drops, autosave snapshots).
   * Spawns the engine lazily, same as saveProject.
   */
  async inspectProject(
    ref: { path: string } | { documentBase64: string },
  ): Promise<{
    path: string;
    project: Record<string, unknown>;
    /** #391: set when the response came from the `.recovery` sibling
     *  because the main file was unreadable. */
    recovered?: boolean;
  }> {
    await this.ensureEngine();
    const client = this.client;
    if (!client) {
      throw new SidecarError(ERR.ENGINE_UNAVAILABLE, "no engine client");
    }
    return client.call<{
      path: string;
      project: Record<string, unknown>;
      recovered?: boolean;
    }>(
      "project.open",
      ref,
    );
  }

  /**
   * `score.edit` (#115, spec 13): apply one rhythm edit (setDuration /
   * shiftOnset / toggleTie) against the canonical scoreDocument. Returns
   * the rebuilt payload + fresh concert/horn MusicXML + the new
   * content-derived scoreRevision. The engine worker is the same one
   * that produced the score — the call reuses the live client and only
   * spawns lazily when the engine is down.
   */
  async applyScoreEdit(
    scoreDocument: unknown,
    edit: unknown,
  ): Promise<{
    scoreDocument: unknown;
    scoreRevision: string;
    musicXmlConcert: string;
    musicXmlHornF: string;
  }> {
    await this.ensureEngine();
    const client = this.client;
    if (!client) {
      throw new SidecarError(ERR.ENGINE_UNAVAILABLE, "no engine client");
    }
    return client.call<{
      scoreDocument: unknown;
      scoreRevision: string;
      musicXmlConcert: string;
      musicXmlHornF: string;
    }>("score.edit", { scoreDocument, edit });
  }

  /**
   * `export.midi` (#256): canonical playback MIDI for a scoreDocument —
   * the engine's exporter keeps velocity / pitch bend / swing / tempo
   * map that the client-side MusicXML→MIDI rebuild loses. Spawns the
   * engine lazily like applyScoreEdit.
   */
  async exportMidi(scoreDocument: unknown): Promise<{ midiBase64: string }> {
    await this.ensureEngine();
    const client = this.client;
    if (!client) {
      throw new SidecarError(ERR.ENGINE_UNAVAILABLE, "no engine client");
    }
    return client.call<{ midiBase64: string }>("export.midi", {
      scoreDocument,
    });
  }

  // ---- jobs --------------------------------------------------------------------

  /** The jobKind to request: `transcription` when the engine advertises
   *  it, else the spike stand-in (documented bridge). */
  private transcriptionJobKind(): string {
    const kinds = this.snap.capabilities?.jobKinds;
    if (Array.isArray(kinds) && kinds.includes(TRANSCRIPTION_JOB_KIND)) {
      return TRANSCRIPTION_JOB_KIND;
    }
    return FALLBACK_JOB_KIND;
  }

  /**
   * `score.transcribe` → `job.start`. Explicit user action only — retry is
   * never silent (issue rule). Resolves once the job is accepted; progress
   * arrives as job.event frames afterwards.
   */
  async startTranscription(params: unknown = {}): Promise<void> {
    if (this.snap.job && !isSettled(this.snap.job)) {
      throw new SidecarError(ERR.JOB_ALREADY_RUNNING, "a job is already running");
    }
    this.update({ failure: null, lastResult: null, reviewIssueCount: 0 });
    await this.ensureEngine();
    const client = this.client;
    if (!client) {
      throw new SidecarError(ERR.ENGINE_UNAVAILABLE, "no engine client");
    }
    const kind = this.transcriptionJobKind();
    let accepted: JobStartResult;
    try {
      accepted = await client.startJob(kind, params);
    } catch (e) {
      // job.start itself was rejected (request timeout, INVALID_PARAMS, a
      // racing JOB_ALREADY_RUNNING). Surface an honest failure rather than
      // leaving the screen on a job that never existed — unless crash
      // supervision already set a stronger one (don't downgrade it).
      if (!this.snap.failure) {
        this.update({
          failure: {
            kind: "transcriptionFailed",
            detail: e instanceof Error ? e.message : String(e),
            errorCode: e instanceof SidecarError ? e.code : undefined,
          },
        });
      }
      throw e;
    }
    this.update({
      job: createJobView(accepted.jobId, kind, this.now()),
    });
  }

  /**
   * `job.cancel` — cooperative (PROTOCOL.md): the job ends in a terminal
   * `cancelled` event at the next checkpoint, so this resolves while the
   * job is still finishing. The UI shows the honest `cancelling` state
   * until the terminal event arrives.
   */
  async cancelTranscription(): Promise<void> {
    const job = this.snap.job;
    const client = this.client;
    if (!job || isSettled(job) || !client) return;
    if (job.phase === "cancelling") return;
    this.update({ job: markCancelling(job) });
    try {
      await client.cancelJob(job.jobId);
    } catch (e) {
      if (e instanceof SidecarError && e.code === ERR.JOB_NOT_FOUND) {
        // The job already reached a terminal event — fine, it wins.
        return;
      }
      // The cancel request itself failed — restore the honest running
      // state so the button does not lie about a pending cancel. Fold the
      // flag back onto the CURRENT view so progress/stage events that
      // arrived in the meantime are not lost.
      const current = this.snap.job;
      if (
        current &&
        current.jobId === job.jobId &&
        current.phase === "cancelling"
      ) {
        this.update({ job: { ...current, phase: "running" } });
      }
      throw e;
    }
    // #233: cooperative cancel is a checkpoint poll — a job inside
    // blocking inference (Basic Pitch / pYIN) cannot check the flag
    // until the call returns, so the terminal event may never arrive
    // within a reasonable window. After the grace period, escalate to
    // the documented terminate+restart fallback: mark the job cancelled
    // (before the kill so the exit path cannot label it a crash), kill
    // the worker, and respawn a fresh engine. Audio, prior scores, and
    // project state all live outside the worker and are untouched.
    const graceDeadline = Date.now() + this.cancelGraceMs;
    while (
      this.snap.job?.jobId === job.jobId &&
      !isSettled(this.snap.job) &&
      Date.now() < graceDeadline
    ) {
      await new Promise((r) => setTimeout(r, 40));
    }
    const afterGrace = this.snap.job;
    if (
      afterGrace &&
      afterGrace.jobId === job.jobId &&
      !isSettled(afterGrace) &&
      this.client === client
    ) {
      this.log(
        `cancel grace ${this.cancelGraceMs}ms elapsed — terminating worker`,
      );
      this.update({
        job: { ...afterGrace, phase: "cancelled" },
      });
      const dying = this.client;
      this.client = null;
      if (dying) await dying.terminate();
      try {
        await this.restartEngine();
      } catch {
        // Restart failure is already surfaced via engine/failure state;
        // the job itself stays honestly cancelled.
      }
    }
  }

  // ---- event/state handling ----------------------------------------------------

  private onJobEvent(event: JobEventPayload): void {
    const job = this.snap.job;
    if (!job || event.jobId !== job.jobId) return;
    const next = reduceJobEvent(job, event);
    const patch: Partial<SessionSnapshot> = { job: next };
    if (next.phase === "completed") {
      patch.lastResult = next.result;
      patch.reviewIssueCount = extractReviewIssueCount(next.result);
    } else if (next.phase === "failed" && next.error) {
      // Engine stayed alive, the job failed → 再試行 surface.
      patch.failure = {
        kind: "transcriptionFailed",
        detail: `${next.error.code}: ${next.error.message}`,
        errorCode: next.error.code,
        // #195: the dependency-missing surface names the package.
        errorPackage: (() => {
          const d = next.error.details;
          if (
            next.error.code !== ERR.ENGINE_DEPENDENCY_MISSING ||
            typeof d !== "object" ||
            d === null
          ) {
            return undefined;
          }
          const pkg = (d as Record<string, unknown>).package;
          return typeof pkg === "string" ? pkg : undefined;
        })(),
      };
    }
    this.update(patch);
  }

  private onClientState(state: string): void {
    switch (state) {
      case "ready":
        this.update({ engine: "ready" });
        break;
      case "starting":
        this.update({ engine: "starting" });
        break;
      case "closed":
        this.update({ engine: "closed" });
        break;
      case "crashed":
      case "unresponsive": {
        const engine = state as EngineStatus;
        const kind: FailureKind =
          state === "crashed" ? "workerCrashed" : "workerNotResponding";
        const code =
          state === "crashed" ? ERR.WORKER_CRASHED : ERR.WORKER_UNRESPONSIVE;
        const job = this.snap.job;
        const patch: Partial<SessionSnapshot> = { engine };
        // ADR-0002: an in-flight job gets NO terminal event from a dead
        // worker — the supervisor marks it failed explicitly.
        if (job && !isSettled(job)) {
          patch.job = markJobDead(job, {
            code,
            message:
              state === "crashed"
                ? "worker process exited while the job was in flight"
                : "worker did not answer the watchdog probe",
          });
          patch.failure = { kind, detail: code, errorCode: code };
        } else if (this.snap.engine === "ready" || this.snap.engine === "starting") {
          // Idle-engine death is reported through `engine` alone — the
          // status bar shows it; no modal error for a silent worker.
        }
        this.update(patch);
        break;
      }
    }
  }

  // ---- terminal bookkeeping ------------------------------------------------------

  /**
   * Clear the settled job record after the UI has consumed the terminal
   * state (completed → scoreReady handoff, cancelled → audioReady). The
   * `lastResult` handoff payload is preserved.
   */
  clearJob(): void {
    const job = this.snap.job;
    if (job && isSettled(job)) this.update({ job: null });
  }

  /** Dismiss the failure surface — the workspace returns to its prior
   *  valid state (audio stays loaded, a prior score is never destroyed). */
  clearFailure(): void {
    if (this.snap.failure) this.update({ failure: null });
  }

  /** Diagnostics text for the 診断情報 dialog (GUI_UX_SPEC §19 fields the
   *  session can honestly report; tool checks belong to UI-060). */
  buildDiagnostics(): string {
    const s = this.snap;
    const lines: string[] = [
      "HornScribe desktop — transcription session",
      `protocolVersion: 1`,
      `engine: ${s.engine}`,
      `engineInfo: ${s.engineInfo ? JSON.stringify(s.engineInfo) : "(none)"}`,
      `jobKinds: ${JSON.stringify(s.capabilities?.jobKinds ?? [])}`,
      `cooperativeCancel: ${String(s.capabilities?.cooperativeCancel ?? "?")}`,
      `cancellationFallback: ${String(s.capabilities?.cancellationFallback ?? "?")}`,
      `job: ${s.job ? `${s.job.jobId} ${s.job.phase}` : "(none)"}`,
      `failure: ${s.failure ? `${s.failure.kind} (${s.failure.detail})` : "(none)"}`,
      "— recent engine diagnostics —",
      ...s.diagnostics.slice(-30),
    ];
    return lines.join("\n");
  }
}

function isSettled(job: JobView): boolean {
  return (
    job.phase === "completed" ||
    job.phase === "cancelled" ||
    job.phase === "failed"
  );
}
